#!/usr/bin/env python3
"""Reproducible ORIGINAL schematic format artwork, not branded product photography."""
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]


def svg(body, *, width=360, height=250, background=None):
    bg = f'<rect width="{width}" height="{height}" fill="{background}"/>' if background else ''
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}"><defs><linearGradient id="metal" x2="1" y2=".4"><stop stop-color="#bdc4b9"/><stop offset=".45" stop-color="#f2f1df"/><stop offset="1" stop-color="#9da99c"/></linearGradient><linearGradient id="dark" x2=".9" y2="1"><stop stop-color="#46564a"/><stop offset="1" stop-color="#25392c"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="4"/></filter></defs>{bg}{body}</svg>\n'''


