def main():
    stale=[]
    for name, content in ART.items():
        path=ROOT/'assets/img'/f'{name}.svg'
        if '--check' in sys.argv:
            if not path.is_file() or path.read_text()!=content:stale.append(str(path.relative_to(ROOT)))
        else:path.write_text(content)
    if stale:
        raise SystemExit('Stale original artwork: '+', '.join(stale))
    print(f'Original schematic artwork: {len(ART)} files current')


if __name__=='__main__':main()
